+const bagStatus = document.getElementById("bag-status");
+const addButtons = Array.from(document.querySelectorAll(".add-button"));
+
+let bagItems = 0;
+
+function updateFilter(selectedFilter) {
+  let visibleCount = 0;
+
+  filterButtons.forEach((button) => {
+    const isActive = button.dataset.filter === selectedFilter;
+    button.classList.toggle("is-active", isActive);
