+const productStatus = document.getElementById("product-status");
+const dealTimer = document.getElementById("deal-timer");
+const bagCount = document.getElementById("bag-count");
+const bagStatus = document.getElementById("bag-status");
+const addButtons = Array.from(document.querySelectorAll(".add-button"));
+
+let bagItems = 0;
+
+function updateFilter(selectedFilter) {
+  let visibleCount = 0;
+
+  filterButtons.forEach((button) => {
+    const isActive = button.dataset.filter === selectedFilter;
+    button.classList.toggle("is-active", isActive);
+    button.setAttribute("aria-pressed", String(isActive));
+  });
+
+  productCards.forEach((card) => {
+    const matches =
+      selectedFilter === "all" || card.dataset.category === selectedFilter;
+
+    card.hidden = !matches;
+
+    if (matches) {
+      visibleCount += 1;
+    }
+  });
+
+  const filterLabel =
+    selectedFilter === "all"
+      ? "all categories"
+      : `${selectedFilter} products`;
+
+  productStatus.textContent = `Showing ${visibleCount} featured items for ${filterLabel}.`;
+}
+
+function updateDealTimer() {
+  const now = new Date();
+  const nextMidnight = new Date(now);
+
+  nextMidnight.setHours(24, 0, 0, 0);
+
+  const distance = nextMidnight.getTime() - now.getTime();
+  const hours = String(Math.floor(distance / 3600000)).padStart(2, "0");
+  const minutes = String(Math.floor((distance % 3600000) / 60000)).padStart(2, "0");
+  const seconds = String(Math.floor((distance % 60000) / 1000)).padStart(2, "0");
+
+  dealTimer.textContent = `${hours}:${minutes}:${seconds}`;
+}
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    updateFilter(button.dataset.filter || "all");
+  });
+});
+
