+  button.addEventListener("click", () => {
+    const productName = button.dataset.productName || "item";
+
+    bagItems += 1;
+    bagCount.textContent = String(bagItems);
+    bagStatus.textContent = `Add to bag confirmed for ${productName}. Bag now has ${bagItems} item${
+      bagItems === 1 ? "" : "s"
+    }.`;
