+  margin-top: auto;
+}
+
+.add-button {
+  min-height: 2.8rem;
+  padding: 0.65rem 1rem;
+  font-weight: 700;
+}
+
+.deal-zone {
+  padding-bottom: 0;
+}
+
+.timer {
+  font-weight: 700;
+}
+
+.deal-layout {
+  align-items: stretch;
+}
+
+.deal-feature {
+  flex: 1.1;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  background:
+    radial-gradient(circle at top right, #f0ddd4 0%, #fff7f2 38%, var(--surface) 55%),
+    var(--surface);
