 const productStatus = document.getElementById("product-status");
 const dealTimer = document.getElementById("deal-timer");
 const bagCount = document.getElementById("bag-count");
 const bagStatus = document.getElementById("bag-status");
 const addButtons = Array.from(document.querySelectorAll(".add-button"));

 let bagItems = 0;

 function updateFilter(selectedFilter) {
   let visibleCount = 0;

