       visibleCount += 1;
     }
   });

   const filterLabel =
     selectedFilter === "all"
       ? "all categories"
       : `${selectedFilter} products`;

   productStatus.textContent = `Showing ${visibleCount} featured items for ${filterLabel}.`;
 }

